import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.il0noOp3.js";const A=JSON.parse('{"title":"WAF — enumerated source for the Analytics technology review","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-analytics-checklist.md","filePath":"frameworks/waf-analytics-checklist.md"}'),o={name:"frameworks/waf-analytics-checklist.md"};function i(n,t,s,c,l,u){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="waf-—-enumerated-source-for-the-analytics-technology-review" tabindex="-1">WAF — enumerated source for the Analytics technology review <a class="header-anchor" href="#waf-—-enumerated-source-for-the-analytics-technology-review" aria-label="Permalink to &quot;WAF — enumerated source for the Analytics technology review&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>waf.analytics.yaml</code> scores the Analytics review. This page enumerates the Well-Architected guidance for Azure Databricks, Azure Event Hubs, Log Analytics and Microsoft Fabric, item by item. The rule file is written against this page only; every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/5eaa8702-ebdb-44cf-8b40-17c3f3b63330/" target="_blank" rel="noreferrer">Analytics — Well-Architected Review</a> (question text not published)</td></tr><tr><td>Framework version</td><td>Azure Well-Architected Framework service guides for Azure Databricks, Event Hubs and Log Analytics (service-guide catalog, Analytics category) and Microsoft Fabric workload guidance, current at extraction</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The service-guide catalog was fetched on 2026-11-25. The Event Hubs and Log Analytics guides were fetched in full. For the Azure Databricks guide the first 260 characters of every configuration-recommendation row were read (the workload design checklists were not), so Databricks items rest on the row titles and need a full re-read at the next recheck. The Fabric overview, reliability and security pages were read from search excerpts. The Fabric cost, operational-excellence and performance-efficiency pages were not read beyond the overview&#39;s one-line focus statements, so those items are summary-level and must be re-read at the next recheck.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The review&#39;s questions are not published. The items below are <strong>Scout&#39;s</strong> reading of the guides and the <code>WAF-ANALYTICS-*</code> ids are Scout&#39;s. Synapse, Data Factory, Purview, Data Explorer and the other Analytics resource types have no Well-Architected service guide in the catalog, so they are not scored here (they are scored by the CAF Analytics rules).</p><p>Sources (the code after each item names the page and section; -C is a workload design checklist bullet, -R a configuration recommendations row):</p><ul><li>[DBX] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-databricks" target="_blank" rel="noreferrer">Architecture best practices for Azure Databricks</a></li><li>[EH] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/event-hubs" target="_blank" rel="noreferrer">Architecture best practices for Azure Event Hubs</a></li><li>[FAB] <a href="https://learn.microsoft.com/azure/well-architected/microsoft-fabric/overview" target="_blank" rel="noreferrer">Microsoft Fabric workloads</a> and its reliability, security, cost optimization, operational excellence and performance efficiency pages</li><li>[LA] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-log-analytics" target="_blank" rel="noreferrer">Architecture best practices for Log Analytics</a></li></ul><p>Log Analytics workspaces now carry location, pricing tier, daily cap, public network access for ingestion and query, local-authentication and access-control flags and workspace replication; Event Hubs namespaces carry zone redundancy, public network access, auto-inflate, tier, capacity, throughput ceiling, geo-replica count, local-authentication, minimum TLS and key source; Databricks workspaces carry virtual network injection, no-public-IP and public network access. An absent boolean is <code>null</code> in the collection, and Newtonsoft JSONPath never matches a missing property with <code>==</code> or <code>!=</code> but does match a <code>null</code> value with <code>!=</code>, so rules where absence is itself the finding (local authentication on) are written as &quot;is not the good value&quot;. Items that mixed a scorable check with something ARM does not carry (cluster settings, geo-DR pairing, table-level RBAC, ingestion alerts) were narrowed to the part that can be scored, and the row says what is left for a human.</p><h2 id="the-enumeration-—-74-items" tabindex="-1">The enumeration — 74 items <a class="header-anchor" href="#the-enumeration-—-74-items" aria-label="Permalink to &quot;The enumeration — 74 items&quot;">​</a></h2><h3 id="reliability-waf-analytics-re-—-16-items" tabindex="-1">Reliability (WAF-ANALYTICS-RE) — 16 items <a class="header-anchor" href="#reliability-waf-analytics-re-—-16-items" aria-label="Permalink to &quot;Reliability (WAF-ANALYTICS-RE) — 16 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ANALYTICS-RE-01</td><td>Databricks clusters autoscale with a minimum of two nodes and a maximum within quota</td><td>❌ Manual — cluster settings are workspace data plane; workspaces attached</td><td>DBX-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-02</td><td>Mission-critical Databricks workloads run across regions with automated backup of code, jobs and cluster configuration</td><td>❌ Manual — workspaces attached with region</td><td>DBX-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-03</td><td>Cluster pools keep prewarmed instances across several VM sizes in a family</td><td>❌ Manual — pool configuration is data plane</td><td>DBX-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-04</td><td>Delta time travel retention and the Unity Catalog metastore are protected</td><td>❌ Manual — data-plane configuration</td><td>DBX-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-05</td><td>Jobs retry with backoff and streaming checkpoints sit on zone-redundant storage</td><td>❌ Manual — job and checkpoint configuration, not ARM</td><td>DBX-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-06</td><td>Event Hubs namespaces are zone redundant</td><td>✅ namespace zoneRedundant</td><td>EH-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-07</td><td>Geo-replication or geo-disaster recovery is configured for regional failure</td><td>✅ <code>eventHubGeoDr</code> <code>geoDrConfigured</code> false and no geo-replication (<code>geoReplicaCount</code> above 1), joined by namespace id; gated on <code>eventHubGeoDrMeasured</code></td><td>EH-RE-C, EH-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-08</td><td>Capacity is planned: throughput units, partition count and auto-inflate suit the load</td><td>❌ Manual — namespaces attached with tier, capacity, auto-inflate and throughput ceiling; the load and the partition count are not collected</td><td>EH-RE-C, EH-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-09</td><td>Alerts cover consumer lag, throughput utilisation and throttling, tied to SLOs</td><td>❌ Manual — metric alert rules attached (estate-wide)</td><td>EH-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-10</td><td>The Log Analytics workspace is in a region with data resilience and co-located with the workload and its collection endpoints</td><td>✅ <code>location</code> against the zone-region list, and <code>replicationEnabled</code>; where the workload and the collection endpoints run is not collected</td><td>LA-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-11</td><td>Critical logs are multicast or exported so they survive a regional outage</td><td>❌ Manual — data-collection routing, not collected per workspace</td><td>LA-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-12</td><td>Data collection rules are single-purpose, and a daily cap with alerts and a retention policy protect ingestion</td><td>❌ Manual — data collection rules attached; the daily cap is scored by WAF-ANALYTICS-CO-11 and retention by RE-13</td><td>LA-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-13</td><td>Workspace retention is at least 30 days</td><td>✅ retentionInDays (Scout threshold of 30)</td><td>LA-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-14</td><td>Workspace health alerts and Workspace Insights are in use</td><td>❌ Manual — scheduled query rules attached (estate-wide)</td><td>LA-RE-R</td></tr><tr><td>WAF-ANALYTICS-RE-15</td><td>Fabric capacity resilience is configured: disaster-recovery setting, dedicated capacities for critical work and surge protection</td><td>❌ Manual — capacity settings are not ARM properties; capacities attached</td><td>FAB-RE</td></tr><tr><td>WAF-ANALYTICS-RE-16</td><td>Fabric capacities are healthy</td><td>✅ capacity state</td><td>FAB-RE</td></tr></tbody></table><h3 id="security-waf-analytics-se-—-22-items" tabindex="-1">Security (WAF-ANALYTICS-SE) — 22 items <a class="header-anchor" href="#security-waf-analytics-se-—-22-items" aria-label="Permalink to &quot;Security (WAF-ANALYTICS-SE) — 22 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ANALYTICS-SE-01</td><td>Databricks workspaces use virtual network injection</td><td>✅ workspace vnetInjected (a customer virtual network id is set)</td><td>DBX-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-02</td><td>Databricks workspaces have a private endpoint</td><td>✅ workspace to private endpoint join</td><td>DBX-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-03</td><td>Databricks clusters use secure cluster connectivity (no public IPs) with SSH off</td><td>✅ workspace noPublicIp (enableNoPublicIp); an absent value is a finding. SSH is not collected</td><td>DBX-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-04</td><td>Identity uses Microsoft Entra SSO with MFA and Conditional Access, and OAuth or service principals instead of personal access tokens</td><td>❌ Manual — identity policy is read from Microsoft Graph and the workspace, not this collection</td><td>DBX-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-05</td><td>Unity Catalog governs data access across workspaces</td><td>❌ Manual — data-plane governance</td><td>DBX-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-06</td><td>Workspace storage uses customer-managed keys where required</td><td>❌ Manual — the workspace encryption block is not projected; workspaces attached</td><td>DBX-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-07</td><td>Secrets live in Key Vault-backed scopes</td><td>❌ Manual — data-plane configuration</td><td>DBX-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-08</td><td>IP access lists and egress controls limit network reach</td><td>❌ Manual — IP access lists are workspace configuration, not collected; workspaces that accept public network access attached</td><td>DBX-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-09</td><td>Audit logging, enhanced security and compliance settings and the Security Analysis Tool are in use</td><td>❌ Manual — data-plane configuration</td><td>DBX-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-10</td><td>Event Hubs namespaces have public network access disabled</td><td>✅ namespace publicNetworkAccess</td><td>EH-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-11</td><td>Event Hubs authorizes with Microsoft Entra ID and SAS is disabled where managed identities are available</td><td>✅ disableLocalAuth; only an explicit true passes, so an absent flag (SAS on) is a finding</td><td>EH-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-12</td><td>Event Hubs enforces TLS 1.2 or higher</td><td>✅ minimumTlsVersion of 1.0 or 1.1 is a finding; an absent value is the platform default and is not flagged</td><td>EH-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-13</td><td>Event Hubs data is encrypted with customer-managed keys (and double encryption) where required</td><td>❌ Manual — customer-managed keys are requirement-driven (and need Premium or Dedicated); the namespaces whose key source is not Key Vault are attached as evidence</td><td>EH-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-14</td><td>Event Hubs namespaces send diagnostic logs to Log Analytics</td><td>✅ diagnostic-settings coverage for the namespace type</td><td>EH-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-15</td><td>Event Hubs connection strings are in Key Vault, with short-lived SAS where SAS is unavoidable</td><td>❌ Manual — secret handling, not ARM</td><td>EH-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-16</td><td>Log Analytics access is limited to private networks and Microsoft Entra authentication</td><td>✅ public network access for ingestion and query, and disableLocalAuth; an absent disableLocalAuth (keys accepted) is a finding</td><td>LA-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-17</td><td>Workspace access control mode is resource or workspace permissions, with table-level RBAC where needed</td><td>✅ resource-permissions access flag (workspace-only or absent is a finding); table-level RBAC is not collected</td><td>LA-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-18</td><td>Customer-managed keys protect workspace data where required</td><td>❌ Manual — the dedicated-cluster link that carries the key is not projected</td><td>LA-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-19</td><td>Log Analytics workspaces send their own diagnostic and query-audit logs to a destination</td><td>✅ diagnostic-settings coverage for the workspace type</td><td>LA-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-20</td><td>Audit and compliance data is exported to immutable storage and sensitive log data is filtered or obfuscated</td><td>❌ Manual — data-export rules and transformations are not collected</td><td>LA-SE-R</td></tr><tr><td>WAF-ANALYTICS-SE-21</td><td>Fabric workspaces are isolated, with RBAC, workspace identity and managed identities</td><td>❌ Manual — tenant and workspace settings are not ARM properties</td><td>FAB-SE</td></tr><tr><td>WAF-ANALYTICS-SE-22</td><td>Fabric uses private links, managed private endpoints, Conditional Access and customer-managed keys where required</td><td>❌ Manual — tenant settings are not ARM properties; capacities attached</td><td>FAB-SE</td></tr></tbody></table><h3 id="cost-optimization-waf-analytics-co-—-13-items" tabindex="-1">Cost optimization (WAF-ANALYTICS-CO) — 13 items <a class="header-anchor" href="#cost-optimization-waf-analytics-co-—-13-items" aria-label="Permalink to &quot;Cost optimization (WAF-ANALYTICS-CO) — 13 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ANALYTICS-CO-01</td><td>Databricks compute is cost-governed: job clusters, autoscaling, auto-termination and compute policies</td><td>❌ Manual — cluster settings are data plane; workspaces attached</td><td>DBX-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-02</td><td>Serverless SQL warehouses and jobs, pools and Photon are used where they cut cost</td><td>❌ Manual — data-plane configuration</td><td>DBX-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-03</td><td>Databricks reserved capacity covers predictable usage</td><td>❌ Manual — reservations attached</td><td>DBX-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-04</td><td>No Databricks workspace runs on the trial SKU</td><td>✅ workspace sku (trial only; Standard versus Premium is judgement)</td><td>DBX-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-05</td><td>Databricks cost is monitored with system tables, Cost Management budgets and tags</td><td>❌ Manual — budgets attached (estate-wide)</td><td>DBX-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-06</td><td>Delta tables are optimised and vacuumed on a schedule and data formats are efficient</td><td>❌ Manual — data-plane maintenance</td><td>DBX-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-07</td><td>Event Hubs tier, throughput, auto-inflate maximum and retention suit the workload</td><td>❌ Manual — with evidence: each event hub&#39;s retention and whether Capture is on (<code>domains.integration.eventHubEntities</code>), beside the namespaces&#39; tier, capacity and auto-inflate ceiling; whether they suit the workload is not collected</td><td>EH-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-08</td><td>Event Hubs has budgets, policy limits and shutdown automation for non-production</td><td>❌ Manual — budgets attached (estate-wide)</td><td>EH-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-09</td><td>Log Analytics uses a commitment tier or dedicated cluster where volume justifies it</td><td>❌ Manual — workspaces attached with pricing tier and daily cap; ingestion volume is a metric, not collected</td><td>LA-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-10</td><td>Retention, archive, Basic logs and summary rules keep long-term log cost down</td><td>❌ Manual — table plans are not collected</td><td>LA-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-11</td><td>A daily cap guards against runaway cost</td><td>✅ dailyQuotaGb (-1 or absent means no cap); the high-ingestion alerts are not tied to a workspace and are not scored</td><td>LA-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-12</td><td>Microsoft Sentinel logs are in a separate workspace</td><td>❌ Manual — Sentinel workspaces attached</td><td>LA-CO-R</td></tr><tr><td>WAF-ANALYTICS-CO-13</td><td>Fabric capacity is sized to the workload, shared deliberately, paused or scaled by automation and monitored for utilisation</td><td>❌ Manual — utilisation is not collected; capacities attached</td><td>FAB-CO</td></tr></tbody></table><h3 id="operational-excellence-waf-analytics-oe-—-13-items" tabindex="-1">Operational excellence (WAF-ANALYTICS-OE) — 13 items <a class="header-anchor" href="#operational-excellence-waf-analytics-oe-—-13-items" aria-label="Permalink to &quot;Operational excellence (WAF-ANALYTICS-OE) — 13 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ANALYTICS-OE-01</td><td>Databricks workspaces are deployed with ARM or Bicep, with environment parameters</td><td>❌ Manual — deployment method is not an ARM property</td><td>DBX-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-02</td><td>Notebooks and code are in Git with CI/CD</td><td>❌ Manual — practice, not ARM</td><td>DBX-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-03</td><td>Databricks diagnostic settings send platform, audit and cluster logs to Log Analytics with alert rules</td><td>✅ diagnostic-settings coverage for the Databricks workspace type (a setting present; categories and alert rules are not read)</td><td>DBX-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-04</td><td>Pipelines enforce data-quality expectations, and workspace artefacts are backed up</td><td>❌ Manual — data-plane practice</td><td>DBX-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-05</td><td>Cluster lifecycle policies and environment-specific RBAC separate development, test and production</td><td>❌ Manual — workspace configuration</td><td>DBX-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-06</td><td>Event Hubs namespaces and hubs are deployed as code through staged pipelines</td><td>❌ Manual — deployment method is not an ARM property</td><td>EH-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-07</td><td>Event Hubs has dashboards, correlation-aware logging and runbook workbooks</td><td>❌ Manual — workbooks attached (estate-wide)</td><td>EH-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-08</td><td>Azure Policy enforces Event Hubs diagnostics, retention and network restrictions, and load tests precede release</td><td>❌ Manual — policy and test practice, not collected per namespace</td><td>EH-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-09</td><td>Log Analytics workspace architecture is deliberate: number, placement and production versus non-production separation</td><td>❌ Manual — workspaces attached for counting</td><td>LA-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-10</td><td>Log Analytics workspaces are deployed as code, through pipelines, with Azure Policy enforcing standards</td><td>❌ Manual — deployment method is not an ARM property</td><td>LA-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-11</td><td>Workspace health is monitored with Workspace Insights and operation-table alerts</td><td>❌ Manual — scheduled query rules attached (estate-wide)</td><td>LA-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-12</td><td>Workspaces are treated as static and protected from deletion</td><td>❌ Manual — resource locks attached (estate-wide)</td><td>LA-OE-R</td></tr><tr><td>WAF-ANALYTICS-OE-13</td><td>Fabric uses deployment pipelines, Git, automated testing, progressive rollout and workspace monitoring</td><td>❌ Manual — tenant and workspace practice, not ARM</td><td>FAB-OE</td></tr></tbody></table><h3 id="performance-efficiency-waf-analytics-pe-—-10-items" tabindex="-1">Performance efficiency (WAF-ANALYTICS-PE) — 10 items <a class="header-anchor" href="#performance-efficiency-waf-analytics-pe-—-10-items" aria-label="Permalink to &quot;Performance efficiency (WAF-ANALYTICS-PE) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ANALYTICS-PE-01</td><td>Databricks cluster types and autoscale bounds match the workload</td><td>❌ Manual — cluster settings are data plane; workspaces attached</td><td>DBX-PE-R</td></tr><tr><td>WAF-ANALYTICS-PE-02</td><td>Delta tables are optimised, clustered and cached; Photon and adaptive query execution are on</td><td>❌ Manual — data-plane configuration</td><td>DBX-PE-R</td></tr><tr><td>WAF-ANALYTICS-PE-03</td><td>Serverless SQL warehouses serve BI and interactive queries, and streaming triggers match latency needs</td><td>❌ Manual — data-plane configuration</td><td>DBX-PE-R</td></tr><tr><td>WAF-ANALYTICS-PE-04</td><td>Event Hubs tier and partition count suit throughput and retention needs</td><td>❌ Manual — with evidence: each event hub&#39;s partition count (<code>domains.integration.eventHubEntities</code>) beside the namespaces&#39; tier and capacity; throughput needs are not collected</td><td>EH-PE-R</td></tr><tr><td>WAF-ANALYTICS-PE-05</td><td>Standard namespaces have auto-inflate enabled</td><td>✅ Standard tier with auto-inflate not on; Premium and Dedicated scaling is not collected</td><td>EH-PE-R</td></tr><tr><td>WAF-ANALYTICS-PE-06</td><td>Producers and consumers are tuned: batching, prefetch, connection reuse and consumer groups</td><td>❌ Manual — client code, not ARM</td><td>EH-PE-R</td></tr><tr><td>WAF-ANALYTICS-PE-07</td><td>The Log Analytics workspace and its collection endpoints are deployed close to the workload</td><td>❌ Manual — collection endpoints attached; workspace regions are on WAF-ANALYTICS-RE-10, the workload region is not collected</td><td>LA-PE-R</td></tr><tr><td>WAF-ANALYTICS-PE-08</td><td>Slow queries are found with query auditing and data collection rules are split for performance and events</td><td>❌ Manual — data collection rules attached</td><td>LA-PE-R</td></tr><tr><td>WAF-ANALYTICS-PE-09</td><td>Service limits are reviewed and extra workspaces used where limits bind</td><td>❌ Manual — quota values are not collected</td><td>LA-PE-R</td></tr><tr><td>WAF-ANALYTICS-PE-10</td><td>Fabric capacities are right-sized, heavy workloads isolated, and queries, pipelines and refresh optimised</td><td>❌ Manual — utilisation is not collected; capacities attached</td><td>FAB-PE</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>16</td><td>5</td><td>11</td></tr><tr><td>Security</td><td>22</td><td>10</td><td>12</td></tr><tr><td>Cost optimization</td><td>13</td><td>2</td><td>11</td></tr><tr><td>Operational excellence</td><td>13</td><td>1</td><td>12</td></tr><tr><td>Performance efficiency</td><td>10</td><td>1</td><td>9</td></tr><tr><td><strong>Total</strong></td><td><strong>74</strong></td><td><strong>19</strong></td><td><strong>55</strong></td></tr></tbody></table><p>Every automated item is gated on its resources (or its diagnostic-coverage rows) existing, so an estate without them reports the item Not assessed. The rules live in <code>src/assess/rules/waf.analytics.yaml</code>.</p>',24)])])}const p=e(o,[["render",i]]);export{A as __pageData,p as default};
